local UIActionDreamlandBattleEndNode = Class("UIActionDreamlandBattleEndNode")
function UIActionDreamlandBattleEndNode:__init()
    self._data = nil
    self._cb = nil
    self._timeDown = nil
end

function UIActionDreamlandBattleEndNode:__delete()
    self._data = nil
    self._cb = nil
    self._timeDown = nil
end

function UIActionDreamlandBattleEndNode:Awake()
end

function UIActionDreamlandBattleEndNode:Start()
    SetButtonAction(self.Root, Bind(self, self.OnBtnClick))
end

function UIActionDreamlandBattleEndNode:Refresh(data, cb)
    if not data then
        return
    end

    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end
    self._cb = cb

    self._data = data

    self:FillSelf()
end

function UIActionDreamlandBattleEndNode:FillSelf()
    CfUtils.FillText(self.TxtNumber, self._data.lable)
    
    local isUnlock, err = ActionUtils.IsUnlockRegionalPoint(self._data.id)
    CfUtils.SetActive(self.Open, isUnlock)
    CfUtils.SetActive(self.Close, not isUnlock)
    if isUnlock then
        CfUtils.FillText(self.TxtName, self._data.name)

        local likabilityLevel = ActionUtils.GetRegionalPointLikabilityLevel(self._data.id)
        for i = 1, 5 do
            --CfUtils.SetActive(self["ImgLv"..i], likabilityLevel >= i)
            CfUtils.SetUISwitchImage(self["ImgLv"..i], likabilityLevel >= i and 1 or 2)
        end

        local isOpen = ActionUtils.IsOpenAnnihilation(self._data.id)
        CfUtils.SetActive(self.Open.transform:Find("DestroyGroup"), isOpen)
        if isOpen then
            self:FillAnnihilationInfo()
        end
    else
        CfUtils.FillText(self.TxtName2, self._data.name)
        CfUtils.FillText(self.TxtDescription2, err)
    end

    local isShow = checkNumber(self._data.regionSpecShow) == 1 
    CfUtils.SetActive(self.HudNode, isShow)

    if isShow then
        local t = CfUtils.Split(self._data.infoCoordinate)
        self.HudNode.anchoredPosition = Vector3(t[1], t[2], t[3])
        CfUtils.FillImage(self.ImgIcon1, self._data.regionSpec)
        CfUtils.FillImage(self.ImgIcon2, self._data.regionSpec)
    end
end

--歼灭战信息
function UIActionDreamlandBattleEndNode:FillAnnihilationInfo()
    local data = ActionUtils.GetAnnihilationInfo(self._data.id)
    if not data then
        return
    end

    local vo = ActionUtils.GetRegionAnnihilationTypeVo(data.bossTypeId)
    CfUtils.FillImage(self.ImgMonsterHead, vo.bossPortrait2)
    CfUtils.FillText(self.TxtState, localize("歼灭战发生中"))
    CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(data.remainTime))

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        local data = ActionUtils.GetAnnihilationInfo(self._data.id)
        if checkNumber(data.remainTime) <= 0 then
            CfUtils.SetActive(self.Open.transform:Find("DestroyGroup"), false)
            if not isNull(self._timeDown) then
                CDTimerModule.GetInstance():RemoveCD(self._timeDown)
                self._timeDown = nil
            end
            return
        end
        CfUtils.FillText(self.TxtTime, CfUtils.GetTimeHMS(data.remainTime))
    end, CountDownTime, false, true)
end

function UIActionDreamlandBattleEndNode:OnBtnClick()
    if not isNull(self._cb) then
        self._cb()
    end
end

function UIActionDreamlandBattleEndNode:OnDestroy()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionDreamlandBattleEndNode